import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { entryNames, folders, frontmatter } from './format.ts';

/** The index is built from entry frontmatter, so concurrent memory PRs never touch a shared file. */
export function render(dir: string): string {
  let text =
    "# Memory\n\nGenerated by `devkit memory reindex` from each entry's frontmatter. Do not commit or edit.\n";
  for (const folder of folders(dir)) {
    const lines = entryNames(dir, folder).flatMap((name) => {
      const entry = frontmatter(readFileSync(join(dir, folder, name), 'utf8'));
      return typeof entry === 'string'
        ? []
        : [`- [${entry.name}](${folder}/${name}): ${entry.description}`];
    });
    if (lines.length) text += `\n## ${folder}\n\n${lines.join('\n')}\n`;
  }
  return text;
}
